'use strict';
/* CIVINITY V9 — single navigation/router and single UI renderer. No legacy modules. */
const ROOT=(window.CIVINITY_API_BASE||window.location.origin).replace(/\/$/,'');
const API=ROOT+'/api/dispatch';
let estimateResult=null;
const $=(s,root=document)=>root.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>new Intl.NumberFormat('lv-LV',{style:'currency',currency:'EUR'}).format(Number(v)||0);
const dt=v=>v?new Date(v).toLocaleDateString('lv-LV'):'—';
let repairSchedule=[];let companyCatalog=['Civinity Solutions','Civinity Mājas','Inservis'];
const S={token:sessionStorage.getItem('dispatch_token')||'',me:null,objects:[],users:[],tasks:[],page:'home',filter:'all',query:'',pageNo:1,perPage:25,filters:{},company:localStorage.getItem('civinity_company')||'Civinity Solutions',navOpen:{tasks:true,technical:false,reports:false},chat:false};
const roles={administrators:'Administrators',vaditajs:'Nodaļas vadītājs',parvaldnieks:'Pārvaldnieks',meistars:'Meistars',arpakalpojums:'Ārpakalpojums',klients:'Klients'};
const isAdmin=()=>S.me?.role==='administrators';
const canManage=()=>['administrators','vaditajs','parvaldnieks'].includes(S.me?.role);
const status=t=>{let x=(t.status||'').toLowerCase();if(['pabeigts','apstiprinats','completed','closed','done'].includes(x))return 'done';if(t.ticket?.deadline && new Date(t.ticket.deadline)<new Date() && !['done'].includes(x))return 'late';if(['procesa','procesā','in progress','darba','gaida_apstiprinajumu'].includes(x))return 'progress';return 'open'};
const statusName={done:'Pabeigts',late:'Kavēts',progress:'Procesā',open:'Atvērts'};
const statusColor={done:'green',late:'red',progress:'blue',open:'yellow'};
const typeIcon=t=>({'Remonts':'🔧','Apkope':'⚡','Avārija':'💧','Apsekošana':'◈','UGD':'♧','Elektro':'⚡'}[t.ticket?.type]||'◈');
const alertMsg=(m,err=false)=>{let old=$('.statusmsg');old?.remove();const d=document.createElement('div');d.className='statusmsg'+(err?' error':'');d.textContent=m;document.body.append(d);setTimeout(()=>d.remove(),5500)};
async function api(path,method='GET',data){const options={method,headers:{'Authorization':'Bearer '+S.token}};if(data!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(data)}let res;try{res=await fetch(API+path,options)}catch(e){throw Error('Neizdevās sazināties ar serveri. Pārbaudiet savienojumu.')}let json=await res.json().catch(()=>({}));if(!res.ok)throw Error(json.error||json.message||`Servera kļūda ${res.status}`);return json}
async function refresh(){const me=await api('/me');const [objs,ts,us]=await Promise.all([api('/objects'),api('/tasks'),api('/users').catch(e=>{if(me.role==='klients'||me.role==='meistars'||me.role==='arpakalpojums')return [];throw e})]);S.me=me;S.objects=Array.isArray(objs)?objs:[];S.tasks=Array.isArray(ts)?ts:[];S.users=Array.isArray(us)?us:[];repairSchedule=await api('/repair-schedule').catch(()=>[]);const companies=await api('/companies').catch(()=>[]);companyCatalog=[...new Set([...companyCatalog,...companies.map(c=>c.name)])]}
function loginView(reg=false){$('#app').innerHTML=`<div class="login"><div class="loginphoto"><h1>CIVINITY</h1><p>Būvējam vērtību kopā</p></div><div class="loginform"><form class="panel" id="authform"><h1>CIVINITY</h1><p class="muted">${reg?'Jauna konta reģistrācija':'Pārvaldības platforma'}</p><div class="field"><label>E-pasts / Lietotājvārds</label><input name="email" type="email" autocomplete="username" required placeholder="E-pasts"></div><div class="field"><label>Parole</label><input name="password" type="password" autocomplete="${reg?'new-password':'current-password'}" required minlength="${reg?12:1}" placeholder="Parole"></div><button class="btn primary" style="width:100%" type="submit">${reg?'Reģistrēties':'Pieslēgties'}</button><p id="autherror" class="notice error hidden"></p><p><button class="btn small" type="button" id="toggleauth">${reg?'Atpakaļ uz pieslēgšanos':'Reģistrēties'}</button></p></form></div></div>`;$('#toggleauth').onclick=()=>loginView(!reg);$('#authform').onsubmit=async e=>{e.preventDefault();let b=$('#authform button[type=submit]');b.disabled=true;const data=Object.fromEntries(new FormData(e.currentTarget));try{let r=await api(reg?'/register':'/login','POST',data);if(reg){loginView();alertMsg('Reģistrācija nosūtīta administratoram apstiprināšanai')}else{S.token=r.token;sessionStorage.setItem('dispatch_token',r.token);await boot()}}catch(err){$('#autherror').textContent=err.message;$('#autherror').classList.remove('hidden')}finally{b.disabled=false}}}
function sidebar(){let n=(page,title,ico)=>`<button class="nav ${S.page===page?'active':''}" data-go="${page}"><span class="ico">${ico}</span>${title}</button>`;let group=(key,title,ico,links)=>`<button class="nav" data-expand="${key}"><span class="ico">${ico}</span>${title}<span class="chev">${S.navOpen[key]?'⌄':'›'}</span></button>${S.navOpen[key]?`<div class="subnav">${links.map(x=>n(...x)).join('')}</div>`:''}`;return `<aside class="sidebar" id="sidebar"><div class="brand">CiViNiTY</div><div class="slogan">Būvējam vērtību kopā</div><div class="companybox"><label>Uzņēmums</label><select id="company">${companyCatalog.map(c=>`<option ${S.company===c?'selected':''}>${c}</option>`).join('')}</select></div>${n('home','Sākums','⌂')}${group('tasks','Uzdevumi','☷',[['tasks','Saraksts','≡'],['newtask','Jauns uzdevums','＋'],['stats','Statistika','▥']])}${n('objects','Objekti','▤')}${n('estimates','Tāmes','▦')}${n('inspections','Apsekošana','▧')}${group('reports','Atskaites','▣',[['reports','Dokumentu pārskats','▣'],['pn','PN akti','▤'],['monthly','Mēneša atskaites','▥']])}${group('technical','Tehniskā pārvaldība','⚙',[['technical','Remontdarbu plāns','▦'],['quality','Darbu kontrole','✓']])}${n('companies','Uzņēmumi','▣')}${isAdmin()?n('accounts','Kontu pārvaldība','♙'):''}</aside>`}
function shell(){const a=$('#app');a.innerHTML=`<div class="layout">${sidebar()}<div class="main"><header class="topbar"><div class="v94-company-title">Uzņēmums: <strong>${esc(S.company)}</strong></div><button class="btn menu-toggle" id="menubtn">☰</button><input class="search" id="globalsearch" placeholder="Meklēt uzdevumus, objektus, tāmes, dokumentus…" value="${esc(S.query)}"><select id="language"><option>LV</option></select><button class="btn profile" id="profile">${esc(S.me?.name||'Profils')} ▾</button></header><main class="content" id="view"></main></div></div><button class="chatbutton" id="chatbtn" aria-label="myCi">myC<span style="color:#64bdf6">i</span></button><div id="chatmount"></div>`;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>{S.navOpen[b.dataset.expand]=!S.navOpen[b.dataset.expand];shell();render()});$('#company').onchange=e=>{S.company=e.target.value;localStorage.setItem('civinity_company',S.company);alertMsg('Izvēlēts uzņēmums: '+S.company)};$('#menubtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#globalsearch').oninput=e=>{S.query=e.target.value;if(['tasks','home','objects','accounts'].includes(S.page))render()};$('#profile').onclick=()=>openModal(`<h2>Profils</h2><p>${esc(S.me.name)} · ${esc(S.me.email)}</p><p>${esc(roles[S.me.role]||S.me.role)}</p><div class="actions">${isAdmin()?'<button class="btn primary" data-go="accounts">Kontu pārvaldība</button>':''}<button class="btn" id="logout">Iziet</button></div>`);$('#chatbtn').onclick=()=>{S.chat=!S.chat;renderChat()};renderChat()}
function renderChat(){const el=$('#chatmount');if(!el)return;el.innerHTML=S.chat?`<div class="chatpanel"><div class="panel" style="margin:0;padding:12px;border:0;border-bottom:1px solid #ddd"><b>myCi</b> <button class="btn small" style="float:right" id="chatclose">×</button></div><div class="messages" id="messages"><p class="muted">Palīgs uzdevumu un objektu meklēšanai. Ievadiet jautājumu.</p></div><form class="composer" id="chatform"><input name="q" placeholder="Jautājums…" required><button class="btn primary">↗</button><button type="button" class="btn" id="mic">🎙</button></form></div>`:'';if(!S.chat)return;$('#chatclose').onclick=()=>{S.chat=false;renderChat()};$('#chatform').onsubmit=e=>{e.preventDefault();const q=e.target.elements.q.value.trim();if(!q)return;$('#messages').innerHTML+=`<p><b>Jūs:</b> ${esc(q)}</p>`;const matches=S.tasks.filter(t=>JSON.stringify(t).toLowerCase().includes(q.toLowerCase())).slice(0,6);$('#messages').innerHTML+=`<p><b>myCi:</b> ${matches.length?matches.map(t=>esc(t.number+' — '+(t.ticket?.title||t.description))).join('<br>'):'Neatradu atbilstošus uzdevumus pašreiz ielādētajos datos.'}</p>`;e.target.reset()};$('#mic').onclick=()=>{const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){alertMsg('Šajā pārlūkā balss atpazīšana nav pieejama',true);return}const r=new R();r.lang='lv-LV';r.onresult=e=>{$('#chatform input').value=e.results[0][0].transcript};r.start()}}
function go(p){S.page=p;S.pageNo=1;S.filter='all';shell();render();window.scrollTo(0,0)}
function header(title,sub='',action=''){return `<div class="heading"><div><h1>${title}</h1>${sub?`<p class="muted">${sub}</p>`:''}</div>${action}</div>`}
function metrics(){const total=S.tasks.length,done=S.tasks.filter(t=>status(t)==='done').length,late=S.tasks.filter(t=>status(t)==='late').length,progress=S.tasks.filter(t=>status(t)==='progress').length;return {total,done,late,progress,open:total-done-progress-late}}
function cards(data){return `<div class="cards">${data.map(x=>`<div class="card"><div class="muted">${x[0]}</div><div class="big">${x[1]}</div><div class="muted">${x[2]||''}</div></div>`).join('')}</div>`}
function home(){
 const m=metrics(), active=m.total-m.done;
 const sums=S.tasks.reduce((n,t)=>n+Number(t.ticket?.estimated_cost||t.ticket?.estimated_amount||t.ticket?.amount||0),0);
 const percent=n=>m.total?Math.round(n/m.total*100):0;
 const due=repairSchedule.filter(x=>x.state!=='izpildits').sort((a,b)=>new Date(a.due)-new Date(b.due)).slice(0,5);
 const recent=[...S.tasks].sort((a,b)=>new Date(b.created_at||b.created||0)-new Date(a.created_at||a.created||0)).slice(0,4);
 const kpis=[['▤','Aktīvi uzdevumi',active,'blue','tasks'],['✓','Izpildīti uzdevumi',m.done,'green','tasks'],['⚠','Kavēti uzdevumi',m.late,'red','tasks'],['▱','Aktīvi objekti',S.objects.length,'blue','objects'],['€','Darbu apjoms (bez PVN)',fmt(sums),'blue','stats']];
 const tabs=[['all','Visi',m.total],['progress','Procesā',m.progress],['late','Kavēti',m.late],['done','Izpildīti',m.done]];
 const row=t=>`<div class="v94-feedrow"><span class="v94-feed-icon">▣</span><span>${esc(t.ticket?.title||t.description||t.number||'Uzdevums')}</span><small>${esc(t.number||('#'+t.id))}</small></div>`;
 return `<div class="v94-dashboard">
 <section class="v94-banner" aria-label="CIVINITY ēku pārvaldība"></section>
 <div class="v94-kpis">${kpis.map(([icon,title,num,color,link])=>`<button class="v94-kpi" data-go="${link}"><span class="v94-kpi-icon ${color}">${icon}</span><span><strong>${esc(num)}</strong><small>${title}</small></span><span class="v94-kpi-arrow">›</span></button>`).join('')}</div>
 <div class="v94-dashboard-grid"><div class="v94-left">
 <div class="v94-actions">${[['＋','Jauns uzdevums','newtask'],['▱','Izveidot tāmi','estimates'],['▤','Jauns apsekošanas akts','inspections'],['▣','Izveidot PN-aktu','pn'],['♙','Pievienot lietotāju','accounts'],['▥','Pievienot objektu','objects']].filter(x=>x[2]!=='accounts'||isAdmin()).map(([i,n,g],idx)=>`<button class="v94-action ${idx===0?'main-action':''}" data-go="${g}"><span>${i}</span><small>${n}</small></button>`).join('')}</div>
 <section class="v94-panel v94-taskpanel"><div class="v94-section-title"><h2>Aktuālie uzdevumi</h2><div class="v94-mini-tabs">${tabs.map(([key,label,count])=>`<button class="${S.filter===key?'selected':''}" data-status="${key}">${label} (${count})</button>`).join('')}</div><button class="v94-link" data-go="tasks">Skatīt visus →</button></div>${taskTable(true)}</section>
 </div><div class="v94-right"><section class="v94-panel v94-status"><h2>◉ Uzdevumu statuss</h2><div class="v94-status-inner"><div class="v94-donut" style="--done:${percent(m.done)};--progress:${percent(m.progress)};--late:${percent(m.late)}"><strong>${active}</strong><small>Aktīvi</small></div><div class="v94-legend">${[['Izpildīti',m.done,'green'],['Procesā',m.progress,'blue'],['Kavēti',m.late,'red'],['Atvērti',m.open,'gray']].map(([name,n,c])=>`<div><i class="${c}"></i><span>${name}</span><b>${n}</b><small>${percent(n)}%</small></div>`).join('')}</div></div></section>
 <section class="v94-panel"><div class="v94-section-title"><h2>▣ Plānotie remontdarbi</h2><button class="v94-link" data-go="technical">Darbu plāns →</button></div>${due.length?due.map(t=>`<div class="v94-feedrow"><span>${esc(t.title)} · ${esc(t.object)}</span><b>${dt(t.due)}</b></div>`).join(''):'<p class="v94-empty">Nav plānotu remontdarbu</p>'}</section>
 <section class="v94-panel"><h2>◷ Pēdējās darbības</h2>${recent.length?recent.map(row).join(''):'<p class="v94-empty">Vēl nav reģistrētu uzdevumu</p>'}</section></div></div>
 <div class="v94-bottom">${[['▥','Statistika','Uzdevumu un izmaksu analīze','stats'],['▣','Darbu plāns','Plānošana un resursu noslodze','technical'],['♙','Meistari','Izpildītāju pārvaldība','accounts'],['▤','Līgumi','Objektu un apsaimniekošanas līgumi','objects']].filter(x=>x[3]!=='accounts'||isAdmin()).map(([i,n,sub,g])=>`<button data-go="${g}"><span>${i}</span><span><b>${n}</b><small>${sub}</small></span><span>›</span></button>`).join('')}</div>
 </div>`;
}
function taskWorkspace(compact=false){const m=metrics();const cats=[['all','Visi uzdevumi',m.total],['open','Atvērti',m.open],['progress','Procesā',m.progress],['late','Kavēti',m.late],['done','Pabeigti',m.done]];return `<div class="c93-workspace ${compact?'c93-home':''}"><div class="c93-toolbar"><div class="c93-tabs">${cats.map(([k,n,v])=>`<button class="c93-tab ${S.filter===k?'selected':''}" data-status="${k}">${n}<span class="c93-count ${k}">${v}</span></button>`).join('')}</div><button class="btn primary c93-create" data-go="newtask">＋ Jauns<br>uzdevums</button></div><div class="c93-filterbox"><div class="c93-filters"><div class="field"><label>Objekts</label><select data-filter="object"><option value="">Visi objekti</option>${S.objects.map(o=>`<option value="${o.id}" ${S.filters.object==o.id?'selected':''}>${esc(o.name||o.address)}</option>`).join('')}</select></div><div class="field"><label>Statuss</label><select data-filter="status"><option value="">Visi statusi</option>${Object.entries(statusName).map(([v,n])=>`<option value="${v}" ${S.filters.status===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Prioritāte</label><select data-filter="priority"><option value="">Visas</option>${[['high','Augsta'],['normal','Vidēja'],['low','Zema']].map(([v,n])=>`<option value="${v}" ${S.filters.priority===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Meistars</label><select data-filter="worker"><option value="">Visi meistari</option>${S.users.filter(u=>u.role==='meistars').map(u=>`<option value="${u.id}" ${S.filters.worker==u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div><div class="field"><label>Pakalpojums</label><select data-filter="service"><option value="">Visi pakalpojumi</option>${[...new Set(S.tasks.map(t=>t.ticket?.service).filter(Boolean))].map(v=>`<option ${S.filters.service===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Apmaksas veids</label><select data-filter="payment"><option value="">Visi</option><option value="included" ${S.filters.payment==='included'?'selected':''}>Līgumā iekļauts</option><option value="extra" ${S.filters.payment==='extra'?'selected':''}>Papildu darbs</option></select></div><div class="field c93-period"><label>Periods</label><div class="c93-date"><input aria-label="No datuma" data-filter="from" type="date" value="${esc(S.filters.from||'')}"><span>–</span><input aria-label="Līdz datumam" data-filter="to" type="date" value="${esc(S.filters.to||'')}"></div></div></div></div><div id="taskTable">${taskTable(compact)}</div></div>`}
function filteredTasks(){return S.tasks.filter(t=>{let st=status(t);if(S.filter!=='all'&&st!==S.filter)return false;if(S.filters.status&&st!==S.filters.status)return false;if(S.filters.object&&t.object_id!=S.filters.object)return false;if(S.filters.worker&&t.worker_id!=S.filters.worker&&!t.assignee_ids?.includes(Number(S.filters.worker)))return false;if(S.filters.priority&&t.priority!==S.filters.priority)return false;if(S.filters.payment&&t.payment!==S.filters.payment)return false;if(S.filters.service&&t.ticket?.service!==S.filters.service)return false;if(S.filters.from&&t.created?.slice(0,10)<S.filters.from)return false;if(S.filters.to&&t.created?.slice(0,10)>S.filters.to)return false;if(S.query&&!JSON.stringify(t).toLowerCase().includes(S.query.toLowerCase()))return false;return true})}
function taskTable(compact=false){const rows=filteredTasks(),pages=Math.max(1,Math.ceil(rows.length/S.perPage));S.pageNo=Math.min(S.pageNo,pages);const slice=rows.slice((S.pageNo-1)*S.perPage,S.pageNo*S.perPage);return `<div class="c93-tablebox"><div class="tablewrap"><table class="data c93-table"><thead><tr><th>ID ↕</th><th>Tips</th><th>Darbu<br>vadītājs</th><th>Objekts</th><th>Meistars</th><th>Nosaukums /<br>Īss apraksts</th><th>Pakalpojums</th><th>Statuss</th><th>Prioritāte</th><th>Orient.<br>summa</th><th>Izveidots</th><th></th></tr></thead><tbody>${slice.map(t=>{let st=status(t),pr=t.priority||'normal',prio=pr==='high'?'Augsta':pr==='low'?'Zema':'Vidēja';return `<tr data-task="${t.id}" tabindex="0" title="Atvērt uzdevumu"><td><span class="c93-expand">›</span><b>${esc(t.number)}</b></td><td><span class="c93-type">${typeIcon(t)}</span></td><td>${esc(t.ticket?.work_manager||'—')}</td><td>${esc(t.object||'—')}</td><td>${esc(t.worker||'—')}</td><td><span class="truncate" title="${esc(t.description)}">${esc(t.ticket?.title||t.description||'—')}</span></td><td>${esc(t.ticket?.service||t.department||'—')}</td><td><span class="c93-badge ${st}">${statusName[st]}</span></td><td><span class="c93-priority ${esc(pr)}">${prio}</span></td><td class="c93-money">${fmt(t.ticket?.preliminary_price||0)}</td><td>${dt(t.created)}</td><td><button class="c93-more" data-task="${t.id}" aria-label="Atvērt uzdevumu">⋮</button></td></tr>`}).join('')||`<tr><td colspan="12" class="empty">Nav atrastu uzdevumu. Izveidojiet pirmo uzdevumu.</td></tr>`}</tbody></table></div></div><div class="c93-footer"><div class="c93-pagesize">Rādīt <select id="perpage"><option ${S.perPage===10?'selected':''}>10</option><option ${S.perPage===25?'selected':''}>25</option><option ${S.perPage===50?'selected':''}>50</option></select> ierakstus <span class="c93-total">Kopā: ${rows.length} uzdevumi</span></div><div class="c93-pagination"><button class="c93-page" data-page-step="-1" ${S.pageNo===1?'disabled':''}>‹</button>${Array.from({length:Math.min(5,pages)},(_,i)=>{let n=pages<=5?i+1:Math.min(Math.max(1,S.pageNo-2),pages-4)+i;return `<button class="c93-page ${S.pageNo===n?'active':''}" data-page-number="${n}">${n}</button>`}).join('')}${pages>5?`<span class="c93-ellipsis">…</span><button class="c93-page" data-page-number="${pages}">${pages}</button>`:''}<button class="c93-page" data-page-step="1" ${S.pageNo===pages?'disabled':''}>›</button></div></div>`}
function taskForm(){const opts=S.objects.map(o=>`<option value="${o.id}">${esc((o.name||o.address)+' — '+o.address)}</option>`).join('');const masters=S.users.filter(u=>u.role==='meistars'&&u.approved&&u.active);return `${header('Jauns uzdevums','Uzdevuma izveide un nodošana izpildei')}<form id="taskform" class="panel"><h2>Pieteikuma dati</h2><div class="formgrid"><div class="field"><label>Objekts *</label><select name="object_id" required><option value="">Izvēlieties objektu</option>${opts}</select></div><div class="field"><label>Meistars *</label><select name="worker_id" required><option value="">Izvēlieties meistaru</option>${masters.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></div><div class="field"><label>Tips *</label><select name="type"><option>Remonts</option><option>Apkope</option><option>Avārija</option><option>Apsekošana</option><option>Cits</option></select></div><div class="field"><label>Pakalpojums</label><input name="service" placeholder="Santehnika, Elektro…"></div><div class="field"><label>Prioritāte</label><select name="priority"><option value="normal">Vidēja</option><option value="high">Augsta</option><option value="low">Zema</option></select></div><div class="field"><label>Apmaksas veids *</label><select name="payment"><option value="included">Līgumā iekļauts</option><option value="extra">Papildu darbs</option></select></div><div class="field"><label>Darbu vadītājs</label><input name="work_manager" value="${esc(S.me?.name||'')}"></div><div class="field"><label>Izpildes termiņš</label><input type="datetime-local" name="deadline"></div><div class="field"><label>Orientējošā summa, EUR</label><input name="preliminary_price" type="number" min="0" step="0.01"></div><div class="field"><label>Uzņēmums</label><input name="company" value="${esc(S.company)}"></div><div class="field"><label>Izpildītājs / Contractor</label><input name="contractor"></div><div class="field"><label>Statuss</label><select name="ticket_status"><option>Open</option><option>In progress</option></select></div><div class="field span3"><label>Nosaukums *</label><input name="title" required placeholder="Īss darba nosaukums"></div><div class="field span3"><label>Darba apraksts *</label><textarea name="description" required placeholder="Aprakstiet uzdevumu"></textarea><div class="actions"><button type="button" class="btn small" id="speech">🎙 Balss ievade</button></div></div><div class="field span3"><label>Komentārs</label><textarea name="comment" style="min-height:70px"></textarea></div><div class="field span3"><label>Foto un dokumenti (PDF, Word, Excel, attēli, līdz 8 MB katrs)</label><input type="file" name="attachments" id="taskAttachments" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.doc,.docx,.xls,.xlsx,.txt,.csv,.odt,.ods"></div></div><div class="actions" style="justify-content:flex-end;margin-top:20px"><button type="button" class="btn" data-go="tasks">Atcelt</button><button type="submit" class="btn primary">Izveidot uzdevumu</button></div><p class="footnote">* Obligātie lauki. Ja meistaru saraksts ir tukšs, administrators var apstiprināt meistaru sadaļā Kontu pārvaldība.</p></form>`}
function stats(){const m=metrics();const services={};S.tasks.forEach(t=>{const k=t.ticket?.service||t.department||'Cits';services[k]=(services[k]||0)+1});return `${header('Uzdevumi / Statistika','Reālie rādītāji no servera datiem')}${cards([['Kopā uzdevumi',m.total],['Pabeigti',m.done],['Kavēti',m.late],['Procesā',m.progress]])}<section class="panel"><h2>Uzdevumi pa pakalpojumiem</h2>${Object.entries(services).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<p>${esc(k)} <b style="float:right">${v}</b><div style="background:#e8f0f9;border-radius:5px;height:8px"><div style="width:${m.total?v/m.total*100:0}%;background:#2575cf;height:8px;border-radius:5px"></div></div></p>`).join('')||'<p class="empty">Nav datu</p>'}</section>`}
function objectsView(){return `${header('Objekti','Objektu pārvaldība',canManage()?'<button class="btn primary" id="newobject">＋ Jauns objekts</button>':'')}<div class="panel"><div class="tablewrap"><table class="data"><thead><tr><th>Kods</th><th>Nosaukums</th><th>Adrese</th><th>Uzņēmums</th><th>Līgums</th><th>Stundas likme</th><th></th></tr></thead><tbody>${S.objects.filter(o=>JSON.stringify(o).toLowerCase().includes(S.query.toLowerCase())).map(o=>`<tr><td>${esc(o.code)}</td><td>${esc(o.name)}</td><td>${esc(o.address)}</td><td>${esc(o.company)}</td><td>${esc(o.contract)}</td><td>${fmt(o.rate)}</td><td><button class="btn small" data-object="${o.id}">Atvērt</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nav objektu</td></tr>'}</tbody></table></div></div>`}
function accountView(){if(!isAdmin())return '<div class="notice error">Tikai administratoram</div>';let users=S.users.filter(u=>JSON.stringify(u).toLowerCase().includes(S.query.toLowerCase()));return `${header('Kontu pārvaldība','Lietotāju, lomu un piekļuves tiesību administrēšana','<button class="btn primary" id="newuser">＋ Jauns konts</button>')}${cards([['Visi lietotāji',S.users.length],['Aktīvi',S.users.filter(u=>u.active&&u.approved).length],['Gaida apstiprinājumu',S.users.filter(u=>!u.approved).length],['Bloķēti',S.users.filter(u=>!u.active).length]])}<section class="panel"><div class="tablewrap"><table class="data"><thead><tr><th>ID</th><th>Vārds, uzvārds</th><th>E-pasts</th><th>Amats</th><th>Nodaļa</th><th>Loma</th><th>Statuss</th><th>Reģistrācija</th><th>Darbības</th></tr></thead><tbody>${users.map(u=>`<tr><td>${u.id}</td><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.position)}</td><td>${esc(u.department)}</td><td>${esc(roles[u.role]||u.role)}</td><td><span class="pill ${!u.active?'red':u.approved?'green':'yellow'}">${!u.active?'Bloķēts':u.approved?'Aktīvs':'Gaida apstiprinājumu'}</span></td><td>${dt(u.created)}</td><td><button class="btn small" data-user="${u.id}">Rediģēt</button></td></tr>`).join('')}</tbody></table></div></section>`}
function companies(){return `${header('Uzņēmumi','Uzņēmumu kartotēka un rekvizīti')}<div class="panel"><h2>Uzņēmumu saraksts</h2>${companyCatalog.map(c=>`<p><b>${esc(c)}</b> ${S.company===c?'· Aktīvais uzņēmums':''}</p>`).join('')}${isAdmin()?`<form id="companyform" class="formgrid"><div class="field"><label>Jauns uzņēmums</label><input name="name" required></div><div class="field"><label>Reģistrācijas Nr.</label><input name="registration"></div><div class="field"><label>Juridiskā adrese</label><input name="address"></div><button class="btn primary">Pievienot</button></form>`:''}</div>`}

function reports(){return `${header('Atskaites','Dokumentu kategorijas')}<div class="quick">${['Apsekošanas akti','Defektu akti','PN akti','Mēneša atskaites','Cenu piedāvājumi','Rēķini','Tehniskie atzinumi','Dokumentu arhīvs'].map((x,i)=>`<button class="btn" data-go="${i===2?'pn':i===3?'monthly':i===0?'inspections':'reports'}">▤ ${x}</button>`).join('')}</div><p class="footnote">Pieejamie servera ģeneratori: PN akti un rēķinu PDF. Pārējās kategorijas saglabātas navigācijā turpmākai integrācijai.</p>`}
async function pnView(){let rows=await api('/pn');return `${header('PN akti','Pieņemšanas–nodošanas akti')}<section class="panel"><div class="tablewrap"><table class="data"><thead><tr><th>ID</th><th>Periods</th><th>Statuss</th><th>PDF</th><th>Rēķins</th></tr></thead><tbody>${(Array.isArray(rows)?rows:[]).map(p=>`<tr><td>${p.id}</td><td>${esc(p.period||p.month||'')}</td><td>${esc(p.status)}</td><td><button class="btn small" data-pdf="/pn/${p.id}/pdf">PDF</button></td><td><button class="btn small" data-pdf="/invoices/${p.id}/pdf">PDF</button></td></tr>`).join('')||'<tr><td colspan="5">Nav aktu</td></tr>'}</tbody></table></div></section>`}
function qualityView(){const done=S.tasks.filter(t=>status(t)==='done');return `${header('Darbu kontrole','Pabeigto darbu kvalitātes pārbaude')}<section class="panel"><div class="tablewrap"><table class="data"><thead><tr><th>Uzdevums</th><th>Objekts</th><th>Meistars</th><th>Darba apraksts</th><th>Pārbaude</th></tr></thead><tbody>${done.map(t=>`<tr><td>${esc(t.number)}</td><td>${esc(t.object)}</td><td>${esc(t.worker)}</td><td>${esc(t.ticket?.title||t.description)}</td><td><button class="btn small" data-quality="${t.id}">Pārbaudīt</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nav pabeigtu uzdevumu</td></tr>'}</tbody></table></div></section>`}
async function qualityDetail(id){try{const q=await api('/v61/quality/'+id);openModal(`<h2>Darbu kvalitātes pārbaude · UZ-${String(id).padStart(6,'0')}</h2>${(q.checks||[]).map(c=>`<p><span class="pill ${c.ok?'green':'red'}">${c.ok?'Izpildīts':'Nav izpildīts'}</span> ${esc(c.label)}</p>`).join('')}<p>Darba laiks: ${esc(q.hours)} h · Fotogrāfijas: ${esc(q.photos)}</p>`)}catch(e){alertMsg(e.message,true)}}
function placeholder(title,detail){return `${header(title,detail)}<section class="panel"><p class="muted">Šī sadaļa vēl nav pārbūvēta par pilnībā strādājošu V9 moduli. Vecie konfliktējošie ekrāni netiek ielādēti.</p></section>`}
function render(){const v=$('#view');if(!v)return;const p=S.page;let html='';switch(p){case 'home':html=home();break;case 'tasks':html=`<div class="c93-pagehead"><h1>Uzdevumi <span>/</span> <small>Saraksts</small></h1></div>${taskWorkspace()}`;break;case 'newtask':html=taskForm();break;case 'stats':html=stats();break;case 'objects':html=objectsView();break;case 'accounts':html=accountView();break;case 'companies':html=companies();break;case 'reports':html=reports();break;case 'pn':v.innerHTML=header('PN akti')+'<p>Notiek ielāde…</p>';pnView().then(x=>{if(S.page==='pn'){v.innerHTML=x;bindView()}}).catch(e=>{if(S.page==='pn')v.innerHTML='<p class="notice error">'+esc(e.message)+'</p>'});return;case 'monthly':html=monthlyView();break;case 'estimates':html=estimateView();break;case 'inspections':html=inspectionView();break;case 'technical':v.innerHTML=header('Remontdarbu plāns')+'<p>Notiek ielāde…</p>';plansView().then(x=>{if(S.page==='technical'){v.innerHTML=x;bindView()}}).catch(e=>{if(S.page==='technical')v.innerHTML='<p class="notice error">'+esc(e.message)+'</p>'});return;case 'quality':html=qualityView();break;default:html=home()}v.innerHTML=html;bindView()}
function bindView(){document.querySelectorAll('#view [data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('#view [data-status]').forEach(b=>b.onclick=()=>{S.filter=b.dataset.status;S.pageNo=1;render()});document.querySelectorAll('#view [data-filter]').forEach(el=>el.onchange=e=>{S.filters[el.dataset.filter]=e.target.value;S.pageNo=1;render()});document.querySelectorAll('#view [data-page-number]').forEach(b=>b.onclick=()=>{S.pageNo=Number(b.dataset.pageNumber);render()});document.querySelectorAll('#view .c93-table tbody tr[data-task]').forEach(row=>{row.onclick=e=>{if(e.target.closest('button'))return;taskDetail(Number(row.dataset.task))};row.onkeydown=e=>{if(e.key==='Enter')taskDetail(Number(row.dataset.task))}});document.querySelectorAll('#view [data-page-step]').forEach(b=>b.onclick=()=>{S.pageNo+=Number(b.dataset.pageStep);render()});if($('#perpage'))$('#perpage').onchange=e=>{S.perPage=Number(e.target.value);S.pageNo=1;render()};if($('#refreshTasks'))$('#refreshTasks').onclick=async()=>{try{S.tasks=await api('/tasks');render();alertMsg('Dati atjaunoti')}catch(e){alertMsg(e.message,true)}};document.querySelectorAll('#view [data-task]').forEach(b=>b.onclick=()=>taskDetail(Number(b.dataset.task)));document.querySelectorAll('#view [data-object]').forEach(b=>b.onclick=()=>objectDetail(Number(b.dataset.object)));document.querySelectorAll('#view [data-quality]').forEach(b=>b.onclick=()=>qualityDetail(Number(b.dataset.quality)));document.querySelectorAll('#view [data-user]').forEach(b=>b.onclick=()=>userDetail(Number(b.dataset.user)));if($('#newuser'))$('#newuser').onclick=()=>userDetail();if($('#newobject'))$('#newobject').onclick=()=>objectDetail();if($('#taskform'))bindTaskForm();if($('#estimateform'))bindEstimate();if($('#inspectionform'))bindInspection();if($('#monthlyform'))bindMonthly();if($('#planform'))bindPlan();if($('#companyform'))$('#companyform').onsubmit=async e=>{e.preventDefault();try{await api('/companies','POST',Object.fromEntries(new FormData(e.target)));const companies=await api('/companies');companyCatalog=[...new Set([...companyCatalog,...companies.map(c=>c.name)])];shell();render();alertMsg('Uzņēmums pievienots')}catch(err){alertMsg(err.message,true)}};document.querySelectorAll('[data-pdf]').forEach(b=>b.onclick=async()=>{try{const r=await fetch(API+b.dataset.pdf,{headers:{Authorization:'Bearer '+S.token}});if(!r.ok)throw Error('Neizdevās lejupielādēt PDF');const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='CIVINITY.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}catch(e){alertMsg(e.message,true)}})}
function bindTaskForm(){const form=$('#taskform');form.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));const btn=form.querySelector('[type=submit]');btn.disabled=true;const ticket={title:d.title,type:d.type,service:d.service,work_manager:d.work_manager,deadline:d.deadline,company:d.company,ticket_status:d.ticket_status,preliminary_price:d.preliminary_price,contractor:d.contractor,comment:d.comment};try{const t=await api('/tasks','POST',{object_id:Number(d.object_id),worker_ids:[Number(d.worker_id)],description:d.description,priority:d.priority,payment:d.payment,department:d.service,ticket});const files=[...form.querySelector('[name=attachments]').files];if(files.length){await uploadTaskFiles(t.id,files,'creation')}S.tasks=await api('/tasks');alertMsg('Uzdevums izveidots: '+t.number);go('tasks')}catch(err){alertMsg(err.message,true)}finally{btn.disabled=false}};$('#speech').onclick=()=>{const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){alertMsg('Balss ievade nav pieejama',true);return}let r=new R();r.lang='lv-LV';r.onresult=e=>{form.elements.description.value+=' '+e.results[0][0].transcript};r.start()}}
function openModal(body){const el=document.createElement('div');el.className='modalback';el.innerHTML=`<div class="modal">${body}<div style="margin-top:18px"><button class="btn" id="closemodal">Aizvērt</button></div></div>`;document.body.append(el);el.addEventListener('click',e=>{if(e.target===el)el.remove()});$('#closemodal',el).onclick=()=>el.remove();el.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{el.remove();go(b.dataset.go)});if($('#logout',el))$('#logout',el).onclick=async()=>{await api('/logout','POST').catch(()=>{});sessionStorage.removeItem('dispatch_token');S.token='';S.me=null;el.remove();loginView()};return el}
async function uploadTaskFiles(id,files,phase='update'){
 for(const file of files){const fd=new FormData();fd.append('file',file);fd.append('phase',phase);const r=await fetch(API+'/tasks/'+id+'/attachments',{method:'POST',headers:{Authorization:'Bearer '+S.token},body:fd});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(file.name+': '+(j.error||r.status))}
}
async function taskDownload(path,name){const r=await fetch(API+path,{headers:{Authorization:'Bearer '+S.token}});if(!r.ok)throw Error('Neizdevās atvērt dokumentu');const blob=await r.blob(),url=URL.createObjectURL(blob);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function taskDetail(id){const t=S.tasks.find(x=>x.id===id);if(!t)return;
 const el=openModal(`<h2>${esc(t.number)} — ${esc(t.ticket?.title||'Uzdevums')}</h2><p><b>Objekts:</b> ${esc(t.object)} · <b>Meistars:</b> ${esc(t.worker)}</p><form id="editTask"><div class="field"><label>Statuss</label><select name="status"><option value="nodots" ${t.status==='nodots'?'selected':''}>Atvērts</option><option value="procesa" ${t.status==='procesa'?'selected':''}>Procesā</option><option value="pabeigts" ${t.status==='pabeigts'?'selected':''}>Pabeigts</option></select></div><div class="field"><label>Darba apraksts</label><textarea name="description">${esc(t.description)}</textarea></div><div class="field"><label>Paveiktie darbi</label><textarea name="completed">${esc(t.completed||'')}</textarea></div><div class="field"><label>Komentārs</label><textarea name="comment">${esc(t.ticket?.comment||'')}</textarea></div><div class="field"><label>Pievienot foto vai dokumentu</label><input type="file" name="attachments" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.doc,.docx,.xls,.xlsx,.txt,.csv,.odt,.ods"></div><div class="actions" style="margin-top:12px"><button class="btn primary">Saglabāt</button><button class="btn" type="button" id="historyBtn">Vēsture</button>${status(t)==='done'?'<button class="btn primary" type="button" id="actBtn">Sagatavot aktu</button>':''}</div></form><section id="taskFiles" class="task-files"><h3>Pielikumi un akti</h3><p>Ielādē…</p></section>`);
 const loadFiles=async()=>{try{const [files,acts]=await Promise.all([api('/tasks/'+id+'/attachments'),api('/tasks/'+id+'/acts')]);$('#taskFiles',el).innerHTML='<h3>Pielikumi un akti</h3>'+([...files.map(a=>`<button class="btn small" data-file="${a.id}">📎 ${esc(a.filename)} (${esc(a.phase)})</button><button class="btn small" data-delete-file="${a.id}" title="Dzēst pielikumu">×</button>`),...acts.map(a=>`<button class="btn small" data-act="${a.id}">📄 Akts #${a.id} · ${esc(a.company)}</button>`)].join(' ')||'<p class="muted">Pielikumu nav</p>');el.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>taskDownload('/tasks/'+id+'/attachments/'+b.dataset.file));el.querySelectorAll('[data-delete-file]').forEach(b=>b.onclick=async()=>{if(!confirm('Dzēst pielikumu? Darbība tiks saglabāta vēsturē.'))return;try{await api('/tasks/'+id+'/attachments/'+b.dataset.deleteFile,'DELETE');await loadFiles()}catch(e){alertMsg(e.message,true)}});el.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>taskDownload('/tasks/'+id+'/acts/'+b.dataset.act+'/pdf'))}catch(e){$('#taskFiles',el).textContent=e.message}};loadFiles();
 $('#historyBtn',el).onclick=async()=>{try{const h=await api('/tasks/'+id+'/history');openModal(`<h2>Uzdevuma vēsture · ${esc(t.number)}</h2>${h.map(x=>`<div class="history-entry"><b>${esc(x.actor)}</b> · ${esc(new Date(x.at).toLocaleString('lv-LV'))}<br><strong>${esc(x.action)}</strong><p>${esc(x.details||'')}</p></div>`).join('')||'Nav ierakstu'}`)}catch(e){alertMsg(e.message,true)}};
 const actBtn=$('#actBtn',el);if(actBtn)actBtn.onclick=async()=>{try{const object=S.objects.find(o=>o.id===t.object_id);const company=object?.company||S.company;const body=prompt('Paveikto darbu apraksts aktā:',t.completed||t.description||'');if(body===null)return;const a=await api('/tasks/'+id+'/acts','POST',{company,body});await loadFiles();await taskDownload('/tasks/'+id+'/acts/'+a.id+'/pdf');alertMsg('Akts saglabāts uzdevumā')}catch(e){alertMsg(e.message,true)}};
 $('#editTask',el).onsubmit=async e=>{e.preventDefault();const f=e.target;try{await api('/tasks/'+id,'PATCH',{status:f.elements.status.value,description:f.elements.description.value,completed:f.elements.completed.value,ticket:{comment:f.elements.comment.value}});const files=[...f.elements.attachments.files];if(files.length)await uploadTaskFiles(id,files,f.elements.status.value==='pabeigts'?'completion':'update');S.tasks=await api('/tasks');el.remove();render();alertMsg('Uzdevums saglabāts')}catch(err){alertMsg(err.message,true)}}
}

function objectDetail(id){const o=S.objects.find(x=>x.id===id)||{};const el=openModal(`<h2>${id?'Objekta rediģēšana':'Jauns objekts'}</h2><form id="objform"><div class="formgrid">${[['name','Nosaukums'],['address','Adrese'],['code','Objekta kods'],['company','Uzņēmums'],['contract','Līgums'],['customer','Klients'],['rate','Stundas likme']].map(([k,n])=>`<div class="field"><label>${n}</label><input name="${k}" value="${esc(o[k]||'')}"></div>`).join('')}</div><button class="btn primary" style="margin-top:15px">Saglabāt</button></form>`);$('#objform',el).onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!id&&!d.code)delete d.code;try{await api(id?'/objects/'+id:'/objects',id?'PATCH':'POST',d);S.objects=await api('/objects');el.remove();render();alertMsg('Objekts saglabāts')}catch(err){alertMsg(err.message,true)}}}
function userDetail(id){const u=S.users.find(x=>x.id===id)||{};const el=openModal(`<h2>${id?'Rediģēt kontu':'Jauns konts'}</h2><form id="userform"><div class="formgrid">${[['name','Vārds, uzvārds'],['email','E-pasts'],['position','Amats'],['department','Nodaļa']].map(([k,n])=>`<div class="field"><label>${n}</label><input name="${k}" value="${esc(u[k]||'')}" required="${['name','email'].includes(k)?'required':''}"></div>`).join('')}<div class="field"><label>Loma</label><select name="role">${Object.entries(roles).map(([k,v])=>`<option value="${k}" ${u.role===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Statuss</label><select name="approved"><option value="true" ${u.approved?'selected':''}>Apstiprināts</option><option value="false" ${!u.approved?'selected':''}>Gaida apstiprinājumu</option></select></div><div class="field"><label>Aktīvs</label><select name="active"><option value="true" ${u.active!==false?'selected':''}>Jā</option><option value="false" ${u.active===false?'selected':''}>Bloķēts</option></select></div>${!id?'<div class="field"><label>Parole (vismaz 12 zīmes)</label><input name="password" type="password" minlength="12" required></div>':''}</div><div class="actions" style="margin-top:17px"><button class="btn primary">Saglabāt</button>${id?'<button class="btn" type="button" id="resetpw">Mainīt paroli</button>':''}</div></form>`);$('#userform',el).onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.approved=d.approved==='true';d.active=d.active==='true';try{await api(id?'/users/'+id:'/admin/users',id?'PATCH':'POST',d);S.users=await api('/users');el.remove();render();alertMsg('Konts saglabāts')}catch(err){alertMsg(err.message,true)}};if(id)$('#resetpw',el).onclick=async()=>{const pw=prompt('Jauna parole (vismaz 12 zīmes)');if(pw===null)return;try{await api('/admin/users/'+id+'/password','POST',{password:pw});alertMsg('Parole mainīta')}catch(err){alertMsg(err.message,true)}}}

function estimateView(){return `${header('Tāmes / BIMTāme','Detalizēta būvdarbu tāme ar materiālu cenu avotiem')}<form class="panel" id="estimateform"><div class="formgrid"><div class="field"><label>Objekts</label><select name="object_id"><option value="">Izvēlieties objektu</option>${S.objects.map(o=>`<option value="${o.id}">${esc(o.name||o.address)}</option>`).join('')}</select></div><div class="field"><label>Cenu līmenis</label><select name="price_level"><option value="mid">Vidējs</option><option value="low">Ekonomisks</option><option value="high">Augsts</option></select></div><div class="field"><label>Foto (līdz 3)</label><input type="file" name="images" accept="image/*" multiple></div><div class="field span3"><label>Darba apraksts *</label><textarea name="description" required placeholder="Aprakstiet darbus, zināmos apjomus, materiālus un ierobežojumus"></textarea></div></div><button class="btn primary" type="submit">✦ Izveidot tāmi</button><p class="footnote">Cenas bez pārbaudīta avota netiek uzdotas par verificētām. Nepieciešama OPENAI_API_KEY serverī.</p></form><div id="estimateResult">${estimateResult?estimateMarkup(estimateResult):''}</div>`}
function estimateMarkup(r){const rows=r.rows||[];return `<section class="panel"><h2>${esc(r.estimate||'Tāmes rezultāts')}</h2><div class="tablewrap"><table class="data"><thead><tr><th>Darbs / materiāls</th><th>Mērv.</th><th>Daudz.</th><th>Darbs, EUR</th><th>Materiāli, EUR</th><th>Mehānismi, EUR</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.unit)}</td><td>${esc(x.qty)}</td><td>${fmt(x.labor)}</td><td>${fmt(x.material)}</td><td>${fmt(x.machine)}</td></tr>`).join('')}</tbody></table></div><p class="muted">${esc((r.assumptions||[]).join('; '))}</p><div class="actions"><button class="btn primary" data-export="pdf">PDF</button><button class="btn" data-export="xlsx">Excel</button></div></section>`}
async function postRoot(path,data,blob=false){const r=await fetch(ROOT+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!r.ok){const j=await r.json().catch(()=>({}));throw Error(j.error||`HTTP ${r.status}`)}return blob?r.blob():r.json()}
function bindEstimate(){const form=$('#estimateform');form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]');b.disabled=true;b.textContent='Tāme tiek sagatavota…';try{const images=await Promise.all([...form.elements.images.files].slice(0,3).map(file=>new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})));estimateResult=await postRoot('/api/estimate',{description:form.elements.description.value,price_level:form.elements.price_level.value,images});$('#estimateResult').innerHTML=estimateMarkup(estimateResult);bindEstimateExport();alertMsg('Tāme sagatavota')}catch(err){alertMsg(err.message,true)}finally{b.disabled=false;b.textContent='✦ Izveidot tāmi'}};bindEstimateExport()}
function bindEstimateExport(){document.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>{if(!estimateResult)return;try{const o=S.objects.find(x=>x.id==$('#estimateform [name=object_id]').value)||{};const blob=await postRoot('/api/document',{kind:'estimate',format:b.dataset.export,rows:estimateResult.rows,object:o,company:{name:S.company},act:estimateResult.act},true);downloadBlob(blob,'CIVINITY_Tame.'+b.dataset.export)}catch(e){alertMsg(e.message,true)}})}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function inspectionView(){const items=['Ēkas vispārējais stāvoklis','Jumta konstrukcijas un segums','Lietusūdens novadīšana','Apkures sistēma','Ūdensapgāde un kanalizācija','Elektroapgāde','Ventilācija','Ugunsdrošības sistēmas'];return `${header('Apsekošana','Vizuālās apsekošanas akta projekts')}<form id="inspectionform" class="panel"><div class="field"><label>Objekts</label><select name="object_id" required><option value="">Izvēlieties objektu</option>${S.objects.map(o=>`<option value="${o.id}">${esc(o.name||o.address)}</option>`).join('')}</select></div><h2>Apsekošanas punkti</h2>${items.map((x,i)=>`<div class="field" style="margin:15px 0"><label>${i+1}. ${x}</label><select name="state${i}"><option value="nav parbaudits">Nav pārbaudīts</option><option value="atbilst">Atbilst</option><option value="defekts">Konstatēts defekts</option></select><textarea name="note${i}" placeholder="Novērojumi un konstatētie fakti" style="min-height:65px"></textarea></div>`).join('')}<button class="btn primary" type="submit">Lejupielādēt apsekošanas aktu (PDF)</button><p class="footnote">Šis ir aizpildītas vizuālās apskates dokuments, nevis sertificēts tehniskais atzinums.</p></form>`}
function bindInspection(){const f=$('#inspectionform');f.onsubmit=async e=>{e.preventDefault();const obj=S.objects.find(o=>o.id==f.elements.object_id.value)||{};const entries=[...Array(8)].map((_,i)=>({name:f.querySelectorAll('h2~.field label')[i]?.textContent||'Punkts '+(i+1),status:f.elements['state'+i].value,note:f.elements['note'+i].value}));const act={observations:entries.map(x=>x.name+': '+x.status+'. '+x.note).join('\n'),defects:entries.filter(x=>x.status==='defekts').map(x=>x.note).join('; '),recommendations:'',limitations:'Vizuālā apsekošana; slēptās konstrukcijas nav pārbaudītas.'};try{const blob=await postRoot('/api/document',{kind:'act',format:'pdf',object:obj,company:{name:S.company},rows:[],act},true);downloadBlob(blob,'CIVINITY_Apsekosana.pdf');alertMsg('Akts sagatavots')}catch(err){alertMsg(err.message,true)}}}
function monthlyView(){const today=new Date();return `${header('Mēneša atskaites','Apstiprinātie darbi izvēlētajā periodā')}<form class="panel" id="monthlyform"><div class="formgrid"><div class="field"><label>Gads</label><input name="year" type="number" value="${today.getFullYear()}"></div><div class="field"><label>Mēnesis</label><input name="month" type="number" min="1" max="12" value="${today.getMonth()+1}"></div><div class="field"><label>Objekts</label><select name="object_id"><option value="">Visi objekti</option>${S.objects.map(o=>`<option value="${o.id}">${esc(o.name||o.address)}</option>`).join('')}</select></div></div><button class="btn primary" style="margin-top:15px">Rādīt atskaiti</button></form><div id="monthlyresult"></div>`}
function bindMonthly(){const f=$('#monthlyform');f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));const q=new URLSearchParams(d);try{const r=await api('/monthly?'+q);$('#monthlyresult').innerHTML=`<section class="panel"><h2>Kopā: ${fmt(r.total)}</h2><p>${r.tasks?.length||0} uzdevumi</p>${(r.tasks||[]).map(t=>`<p>${esc(t.number)} — ${esc(t.object)} — ${fmt(t.total)}</p>`).join('')}</section>`}catch(err){alertMsg(err.message,true)}}}
async function plansView(){const plans=await api('/repair-schedule');repairSchedule=plans;return `${header('Remontdarbu plāns','Remontdarbu grafiks un tuvākie izpildes termiņi')}<form class="panel" id="planform"><div class="formgrid"><div class="field"><label>Objekts</label><select name="object_id" required>${S.objects.map(o=>`<option value="${o.id}">${esc(o.name||o.address)}</option>`).join('')}</select></div><div class="field"><label>Darba nosaukums</label><input name="title" required></div><div class="field"><label>Izpildes datums</label><input type="datetime-local" name="due" required></div><div class="field span3"><label>Darbu apraksts</label><textarea name="description"></textarea></div></div><button class="btn primary" style="margin-top:15px">Pievienot grafikam</button></form><section class="panel"><h2>Plānotie remontdarbi</h2><div class="tablewrap"><table class="data"><thead><tr><th>Objekts</th><th>Darbs</th><th>Termiņš</th><th>Statuss</th><th>Darbība</th></tr></thead><tbody>${plans.map(x=>`<tr><td>${esc(x.object)}</td><td>${esc(x.title)}</td><td>${dt(x.due)}</td><td>${esc(x.state)}</td><td><button class="btn small" data-plan-finish="${x.id}" ${x.state==='izpildits'?'disabled':''}>Atzīmēt izpildītu</button></td></tr>`).join('')||'<tr><td colspan="5">Nav plānotu darbu</td></tr>'}</tbody></table></div></section>`}
function bindPlan(){const f=$('#planform');f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));try{await api('/repair-schedule','POST',{...d,object_id:Number(d.object_id)});repairSchedule=await api('/repair-schedule');alertMsg('Darbs pievienots');render()}catch(err){alertMsg(err.message,true)}};document.querySelectorAll('[data-plan-finish]').forEach(b=>b.onclick=async()=>{try{await api('/repair-schedule/'+b.dataset.planFinish,'PATCH',{state:'izpildits'});render()}catch(e){alertMsg(e.message,true)}})}

async function boot(){try{await refresh();shell();render()}catch(e){sessionStorage.removeItem('dispatch_token');S.token='';loginView();alertMsg(e.message,true)}}
if(S.token)boot();else loginView();
